tape( 'the function supports accessor arrays', function test( t ) {
	var fixtures;
	var expected;
	var ybuf;
	var data;
	var out;
	var ap;
	var x;
	var y;
	var i;

	fixtures = [ rxpyp, cxpyp, rxoyt, cxoyt, rxpyn, cxpyn, rxnyp, cxnyp, rxnyn, cxnyn ];
	for ( i = 0; i < fixtures.length; i++ ) {
		data = fixtures[ i ];
		ap = toAccessorArray( copy( data.AP ).slice( data.offsetAP ) );
		x = toAccessorArray( copy( data.x ) );
		ybuf = copy( data.y );
		y = toAccessorArray( ybuf );
		expected = copy( data.y_out );

		out = gspmv( data.order, data.uplo, data.N, data.alpha, ap, x, data.strideX, data.beta, y, data.strideY );
		t.strictEqual( out, y, 'returns the accessor array' );
		t.deepEqual( ybuf, expected, 'returns expected values for fixture '+i );
	}
	t.end();
});
